def build_wire(archive):
    """Independently build the archive wire format straight from the spec."""
    out = bytearray(TAG)
    out += u32(len(archive.items))
    for item in archive.items:
        frame = encode_delta_report_bundle(item)
        out += u32(len(frame))
        out += frame
    return bytes(out)


